\label{thm:rels}
(a) If $g = 2$, then the trivial relations \eqref{triv1}--\eqref{triv2}, the pushed forward relations \eqref{push1}--\eqref{push4}, \eqref{push5}, and the pulled back relations \eqref{rel10pull}--\eqref{rel12pull} generate all relations among the generators of $S_\omega^{13,2}(\overline{\mathcal M}_{g,n})$ in Figure \ref{fig:gentable}.

(b) If $g \geq 3$, then the trivial relations \eqref{triv1}--\eqref{triv2} and pushed forward relations \eqref{push1}--\eqref{push4}, \eqref{push5} generate all relations among the generators of $S_\omega^{13,2}(\overline{\mathcal M}_{g,n})$ in Figure \ref{fig:gentable}.

\label{thm:rh}
We have $H^*(\overline{\mathcal M}_{g,n}) = RH^*(\overline{\mathcal M}_{g,n})$ for the following pairs $(g,n)$:
\begin{gather} \label{goodpairs} (3,9) \qquad (4, 7) \qquad (4, 8) \qquad (5,5) \qquad (5, 6) \qquad (5,7) \\
(6,3) \qquad (6, 4) \qquad (6, 5) \qquad (7, 1) \qquad (7, 2) \qquad (7, 3) \qquad (8, 0) \notag
\end{gather}

\cite[Lemma~4.11]{CLPW24polynomial}\label{lemma:basisGenus1}
The set
    \begin{equation*}
        \{Z_{B \subset A} : |A^c| \geq 3 \text{ or } |A^c| = 2 \text{ and } \min(A^c) < \min(B)\}
    \end{equation*}
    forms a basis for $H^{12,1}(\overline{\mathcal M}_{1,n})$.

\label{lem:rel10}
When $n = 10$, the only relation among the generators is
\begin{equation*} \mathcal L_{[10], \varnothing} = 0 \in H^{15}(\overline{\mathcal M}_{2,10}).
\end{equation*}

\label{lem:rel11}
When $n = 11$, all relations among the generators come from \eqref{rel10pull} together with the relation
\begin{equation*} \mathcal D_{[11] \smallsetminus i, i} + \mathcal L_{[11] \smallsetminus i, i} + 24  \cdot \mathcal S^0_{[11] \smallsetminus i, i, \varnothing} = 0 \in H^{15}(\overline{\mathcal M}_{2,11})
\end{equation*}
for $i = 1, \ldots, 11$.

\label{rel12}
When $n = 12$, all relations among the generators come from \eqref{rel10pull} and \eqref{rel11pull} together with the relations
\begin{equation*} 
M_{jk} = (-1)^{k} M_{1j} - (-1)^{j} M_{1k}
\end{equation*}
for all $j,k \in \{2, \ldots, 12\}$, $j < k$.

\label{lemma:pullbacksMij}
     Let $V \subseteq H^{15}(\overline{\mathcal M}_{2,12})$ be the span of all $M_{ij}$. For any subset $A \subseteq [n]$ of cardinality $|A| = 12$, let $\pi_{[n] \setminus A}: \overline{\mathcal M}_{2,n} \rightarrow \overline{\mathcal M}_{2,A}$ be the forgetful morphism and set $V_A \coloneqq \pi_{[n] \setminus A}^\ast(V) \subseteq H^{15}(\overline{\mathcal M}_{2,n})$. Then the sum $\sum_{A \subseteq [n]} V_A$ is direct. Equivalently, the dimension of the latter is $11 \cdot \binom{n}{12}$ and, as $\mathbb{S}_n$-representations,
    \begin{equation*}
        \sum_{A \subseteq [n]} V_A \cong \mathrm{Ind}_{\mathbb{S}_{12} \times \mathbb{S}_{n-12}}^{\mathbb{S}_n} V_{2,1^{10}}.
    \end{equation*}

For any $2$-element subset $\{x,y\} \subseteq [n]$, let
    \begin{equation*}
         \theta_{xy}: \overline{\mathcal M}_{2,([n]\setminus xy) \cup p} \cong \overline{\mathcal M}_{2,([n]\setminus xy) \cup p} \times \overline{\mathcal M}_{0, \{x,y,q\}} \rightarrow \overline{\mathcal M}_{2,n}
    \end{equation*}
   be the map that glues $p$ and $q$. We first assume $\{x,y\} \subseteq A$. Then
   \begin{equation*}
       \theta_{xy}^\ast \pi_{[n] \setminus A}^\ast(V) = \pi_{[n] \setminus A}^\ast \tilde{\theta}_{xy}^\ast(V),
   \end{equation*}
   where $\tilde{\theta}_{xy}$ is the same map as $\theta_{xy}$ with the set $[n]$ replaced by $A$. We claim $\tilde{\theta}_{xy}^\ast(V) = 0$. Indeed, this follows by computing the pullback of each term in $M_{ij}$ using the excess intersection formula on decorated graphs, as we now explain. 

   Let $X = A \setminus\{i,j\}$.
   The pullbacks of the terms in $M_{ij}$ vanish individually if $\{i,j\} \neq \{x,y\}$. If $\{i,j\} = \{x,y\}$, the only possible non-vanishing K\"unneth component of the pullback is $H^{15} \otimes H^0$. Since $i$ and $j$ are not on the same vertex, the third and fourth graphs appearing in the definition \eqref{Mij-def} of $M_{ij}$ vanish under pullback to this boundary divisor. We then obtain the following expression for the $H^{15}$ K\"unneth factor of the pullback $\tilde{\theta}_{ij}^*M_{ij}$. The equality of the first line with the second line follows by expanding the $\psi_s$ class using the relations in $H^2(\overline{\mathcal M}_{1,2})$ from \cite[Theorem 2.2(c)]{AC98}:

