    \node[auxiliary graph label,above] at (0.875,.7) {$H^{13}\otimes H^2$};

    \end{tikzpicture} 
  }}}} 

 with $X' = \emptyset$. By Lemmas~\ref{lemma:vanishingGenus2} and~\ref{lemma:D'vanishingGenus2}, the pullbacks of the $\mathcal D'$ and $\mathcal L'$ classes all vanish. By Lemma~\ref{lemma:intersectionTableH13xH2}, the pullbacks also vanish for all the $\mathcal D$ and $\mathcal S^1$, as well as the $\mathcal S^0_{B,X,Y}$ and $\mathcal N'_{B,X,Y}$ with $Y \neq \varnothing$.
Moreover, we have already shown that $\ell_{B,X} = 0$ for $|X| = 1$.
We break the remaining generators into four groups according to the shape of their $H^{13}$ K\"unneth component under this pullback.
\begin{enumerate}
    \item[(I)] The $\mathcal S^0_{B,X,\varnothing}$ with $|X|= 2$ and $\mathcal L_{B,X}$ with $|X| = 2$ both yield 
$Z_{B \subset A}$ classes in $H^{13}(\overline{\mathcal M}_{1,[n] \cup s})$ with $A^c = X \cup s$. In particular, $s \in A^c$ and $|A^c| = 3$.
\item[(II)] The 
$\mathcal S^0_{B,X,\varnothing}$ with $|X|> 2$ yield 
$Z_{B \subset A}$ classes in $H^{13}(\overline{\mathcal M}_{1,[n] \cup s})$ with $A^c = X \cup s$. In particular, $s \in A^c$ and $|A^c| > 3$.
\item[(III)] The $\mathcal S^0_{B, i, \varnothing}$ yield $Z_{B \subset A}$ with $A^c = \{i, s\}$. In particular, $|A^c| = 2$ and $s \in A^c$. 
\item[(IV)] The $\mathcal N'_{B,X, \varnothing}$
yield $Z_{B \subset A}$ classes 
with $A = X^c \cup s$. In particular, $s \notin A^c$.
Additionally, our assumption that if $|X| = 2$, then $q \notin B$ and $\min(X) < \min(B)$ ensures that the resulting $Z_{B \subset A}$ satisfy $\min(A^c) < \min(B)$ when $|A^c| = 2$.
\end{enumerate}
We now apply Lemma
~\ref{lemma:basisGenus1} to $H^{13}(\overline{\mathcal M}_{1,[n] \cup s})$, using an ordering in which $s$ is minimal.
In particular, the classes in (II), (III) and (IV) are independent  modulo those in (I).     
Thus, we conclude that 
$s^0_{B,X,\varnothing} = 0$ for $|X| \geq 3$, and $|X| = 1$, and $n_{B, X, \emptyset} = 0$ for all $X$.


